// cspell:ignore testdata
/* eslint-disable unicorn/no-null */

import { describe, expect, test } from "@jest/globals";
import { assertDefined } from "complete-common";
import { z } from "zod";
// These JSON references are generated by Go, not exported by an npm package.
/* eslint-disable @typescript-eslint/no-restricted-imports, import-x/no-relative-packages */
import alternating from "../../../../server/src/testdata/compatibility/alternating-clue-restriction.json";
import starved from "../../../../server/src/testdata/compatibility/clue-starved-discard.json";
import emptyRejected from "../../../../server/src/testdata/compatibility/empty-clue-rejected.json";
import cycling from "../../../../server/src/testdata/compatibility/empty-clues-card-cycle.json";
import genius from "../../../../server/src/testdata/compatibility/genius-two-actions-hidden-partner.json";
import hole from "../../../../server/src/testdata/compatibility/hole-hidden-play.json";
import legacy from "../../../../server/src/testdata/compatibility/legacy-prefixed-deal.json";
import recovery from "../../../../server/src/testdata/compatibility/legacy-retry-recovery.json";
import inverted from "../../../../server/src/testdata/compatibility/orange-live-inversion.json";
import pink from "../../../../server/src/testdata/compatibility/pink-rank-touch.json";
import prism from "../../../../server/src/testdata/compatibility/prism-rank-color.json";
import rainbow from "../../../../server/src/testdata/compatibility/rainbow-color-touch.json";
import reversed from "../../../../server/src/testdata/compatibility/reversed-play.json";
import sudoku from "../../../../server/src/testdata/compatibility/sudoku-stack-conflict.json";
import upOrDown from "../../../../server/src/testdata/compatibility/up-or-down-start.json";
/* eslint-enable @typescript-eslint/no-restricted-imports, import-x/no-relative-packages */
import { charactersInit } from "../charactersInit";
import { ClueType } from "../enums/ClueType";
import { getVariant } from "../gameData";
import type { GameMetadata } from "../interfaces/GameMetadata";
import { options } from "../interfaces/Options";
import { getDefaultMetadata } from "../metadata";
import { isCardTouchedByClue, msgClueToClue } from "../rules/clues";
import { cardOrder } from "../types/CardOrder";
import { colorIndex } from "../types/ColorIndex";
import { playerIndex } from "../types/PlayerIndex";
import { rank } from "../types/Rank";
import { rankClueNumber } from "../types/RankClueNumber";
import { suitIndex } from "../types/SuitIndex";
import { gameReducer } from "./gameReducer";
import { getInitialGameState } from "./initialStates/initialGameState";

// This validates CLIENT projections of Go-accepted events, not TS command acceptance. Go
// generates/checks the corpus through real commandAction and committed WebSocket effects; see
// server/src/compatibility_test.go for format, regeneration, and the explicit normalization
// boundary.
const identity = {
  order: cardOrder,
  suitIndex: z.union([suitIndex, z.literal(-1)]),
  rank: z.union([rank, z.literal(-1)]),
  playerIndex,
};
const clue = z.discriminatedUnion("type", [
  z.object({ type: z.literal(ClueType.Color), value: colorIndex }),
  z.object({ type: z.literal(ClueType.Rank), value: rankClueNumber }),
]);
const strikeNumber = z.union([z.literal(1), z.literal(2), z.literal(3)]);
const event = z.discriminatedUnion("type", [
  z.object({ type: z.literal("draw"), ...identity }),
  z.object({ type: z.literal("play"), ...identity }),
  z.object({
    type: z.literal("discard"),
    ...identity,
    failed: z.boolean(),
  }),
  z.object({ type: z.literal("cardIdentity"), ...identity }),
  z.object({
    type: z.literal("clue"),
    clue,
    giver: playerIndex,
    target: playerIndex,
    list: z.array(cardOrder),
    ignoreNegative: z.boolean().default(false),
  }),
  z.object({
    type: z.literal("strike"),
    num: strikeNumber,
    order: cardOrder,
    turn: z.number(),
  }),
  z.object({
    type: z.literal("status"),
    clues: z.number(),
    score: z.number(),
    maxScore: z.number(),
  }),
  z.object({
    type: z.literal("turn"),
    num: z.number(),
    currentPlayerIndex: playerIndex,
  }),
]);
const card = z.object({
  suitIndex,
  rank,
});
const cardState = z.object({
  Order: z.number(),
  Touched: z.boolean().default(false),
  Played: z.boolean().default(false),
  Discarded: z.boolean().default(false),
  Failed: z.boolean().default(false),
});
const gamePlayer = z.object({
  Hand: z.array(z.number()),
  Character: z.string(),
  CharacterMetadata: z.number(),
});
const state = z.object({
  ActivePlayerIndex: playerIndex,
  ClueTokens: z.number(),
  Score: z.number(),
  Strikes: z.number(),
  Turn: z.number(),
  DeckIndex: z.number(),
  Cards: z.array(cardState),
  Players: z.tuple([gamePlayer, gamePlayer]),
});
const eventList = z.array(event);
const message = z.discriminatedUnion("command", [
  z.object({
    command: z.literal("gameAction"),
    data: z.object({ action: event }),
  }),
  z.object({
    command: z.literal("gameActionList"),
    data: z.object({ list: eventList }),
  }),
  z.object({ command: z.literal("warning"), data: z.unknown() }),
  z.object({ command: z.literal("noteListPlayer"), data: z.unknown() }),
  z.object({ command: z.literal("noteList"), data: z.unknown() }),
]);
const point = z.object({
  state,
  recipients: z.array(z.array(message)),
});
const corpusFixture = z.object({
  version: z.literal(1),
  deck: z.array(card),
  input: z.object({
    name: z.string(),
    options: options.unwrap().strip(),
    deck: z.unknown(),
  }),
  initial: point,
  steps: z.array(point),
});
// Custom short decks are not represented in GameMetadata. Terminal protocol actions also carry -1
// player indexes outside the current GameAction TS type. Those Go-only contracts remain executable
// in TestCompatibilityCorpus.
const fixtures = [
  alternating,
  starved,
  emptyRejected,
  cycling,
  genius,
  hole,
  legacy,
  recovery,
  inverted,
  pink,
  prism,
  rainbow,
  reversed,
  sudoku,
  upOrDown,
];
const characters = [...charactersInit().values()];

describe("Go authority corpus: shared client event projections", () => {
  test.each(fixtures)("$input.name", (raw) => {
    const fixture = corpusFixture.parse(raw);
    expect(fixture.input.deck).toBeNull();
    const variant = getVariant(fixture.input.options.variantName);
    const base = getDefaultMetadata(2, variant.name);
    const assignments = fixture.initial.state.Players.map((player) =>
      characters.find((character) => character.name === player.Character),
    );
    for (const recipient of [0, 1, 2, 3]) {
      const metadata: GameMetadata = {
        ...base,
        options: fixture.input.options,
        ourPlayerIndex: recipient === 1 ? 1 : 0,
        characterAssignments: [
          assignments[0]?.id ?? null,
          assignments[1]?.id ?? null,
        ],
        characterMetadata: [
          fixture.initial.state.Players[0].CharacterMetadata,
          fixture.initial.state.Players[1].CharacterMetadata,
        ],
      };
      let projected = getInitialGameState(metadata);
      for (const [step, checkpoint] of [
        fixture.initial,
        ...fixture.steps,
      ].entries()) {
        const messages = checkpoint.recipients[recipient];
        assertDefined(messages, `Missing recipient ${recipient}, step ${step}`);
        for (const frame of messages) {
          if (
            frame.command !== "gameAction"
            && frame.command !== "gameActionList"
          ) {
            continue;
          }
          const events =
            frame.command === "gameAction"
              ? [frame.data.action]
              : frame.data.list;
          if (frame.command === "gameActionList") {
            projected = getInitialGameState(metadata);
          }
          for (const action of events) {
            if (action.type === "status") {
              // Status is a Go cross-check, not an instruction to overwrite the independently
              // reduced client totals.
              expect(projected.score).toBe(action.score);
              expect(projected.clueTokens).toBe(action.clues);
              continue;
            }
            if (action.type === "clue") {
              const hand = projected.hands[action.target];
              assertDefined(hand, `Missing clue target ${action.target}`);
              const touched = hand.filter((order) => {
                const authoritative = fixture.deck[order];
                assertDefined(authoritative, `Missing reference card ${order}`);
                return isCardTouchedByClue(
                  variant,
                  msgClueToClue(action.clue, variant),
                  authoritative.suitIndex,
                  authoritative.rank,
                );
              });
              expect(touched).toEqual(action.list);
            }
            projected = gameReducer(
              projected,
              action,
              recipient < 2,
              recipient === 3,
              false,
              false,
              metadata,
            );
            if (action.type === "draw" || action.type === "cardIdentity") {
              const projectedCard = projected.deck[action.order];
              assertDefined(
                projectedCard,
                `Missing drawn card ${action.order}`,
              );
              expect(projectedCard.suitIndex).toBe(
                action.suitIndex === -1 ? null : action.suitIndex,
              );
              expect(projectedCard.rank).toBe(
                action.rank === -1 ? null : action.rank,
              );
            }
          }
        }
        expect({
          recipient,
          step,
          hands: projected.hands,
          score: projected.score,
          clues: projected.clueTokens,
          strikes: projected.strikes.length,
          turn: projected.turn.turnNum,
          activePlayer: projected.turn.currentPlayerIndex,
          deckRemaining: projected.cardsRemainingInTheDeck,
        }).toEqual({
          recipient,
          step,
          hands: checkpoint.state.Players.map((player) => player.Hand),
          score: checkpoint.state.Score,
          clues: checkpoint.state.ClueTokens,
          strikes: checkpoint.state.Strikes,
          turn: checkpoint.state.Turn,
          activePlayer: checkpoint.state.ActivePlayerIndex,
          deckRemaining: fixture.deck.length - checkpoint.state.DeckIndex,
        });
        for (const authoritative of checkpoint.state.Cards) {
          const projectedCard = projected.deck[authoritative.Order];
          assertDefined(projectedCard, `Missing card ${authoritative.Order}`);
          expect(projectedCard.numPositiveClues > 0).toBe(
            authoritative.Touched,
          );
          expect(projectedCard.isMisplayed).toBe(authoritative.Failed);
        }
      }
    }
  });
});
